class Repo:
    def noten(self):
        return [1, 2]
class Service:
    def __init__(self, r):
        self.r = r
    def schnitt(self):
        n = self.r.noten()
        return sum(n) / len(n)
print(Service(Repo()).schnitt())

class VM:
    def __init__(self):
        self.obs = []
        self._n = ""
    def set_name(self, n):
        self._n = n
        for f in self.obs:
            f()
vm = VM()
zeige = lambda: print(f"Hallo, {vm._n}!")
vm.obs += [zeige, zeige]
vm.set_name("Max")
